#!/usr/bin/env Rscript

usage <- function() {
  cat(paste(
    "Usage:",
    "  Rscript scripts/render_literature_graph.R --input graph.json --output graph.html [--short-title-overrides titles.json]",
    "",
    "Options:",
    "  --input PATH   Literature graph JSON from build_literature_graph.R.",
    "  --output PATH  Output standalone HTML file.",
    "  --short-title-overrides PATH  Optional JSON sidecar with short_titles keyed by bare ref_id.",
    "  -h, --help     Show this help message.",
    "",
    "The generated HTML loads Cytoscape.js 3.30.4 from unpkg.com.",
    sep = "\n"
  ))
}

parse_args <- function(args) {
  out <- list(help = FALSE, input = NULL, output = NULL, short_title_overrides = NULL)
  i <- 1L
  while (i <= length(args)) {
    key <- args[[i]]
    if (identical(key, "-h") || identical(key, "--help")) {
      out$help <- TRUE
      i <- i + 1L
      next
    }
    if (i == length(args)) stop("Missing value for ", key, call. = FALSE)
    value <- args[[i + 1L]]
    if (identical(key, "--input")) out$input <- value else if (identical(key, "--output")) out$output <- value else if (identical(key, "--short-title-overrides")) out$short_title_overrides <- value else stop("Unknown argument: ", key, call. = FALSE)
    i <- i + 2L
  }
  out
}

parsed <- parse_args(commandArgs(trailingOnly = TRUE))
if (isTRUE(parsed$help)) {
  usage()
  quit(status = 0L)
}
if (is.null(parsed$input) || is.null(parsed$output)) stop("--input and --output are required.", call. = FALSE)
if (!file.exists(parsed$input)) stop("Graph JSON not found: ", parsed$input, call. = FALSE)

graph <- jsonlite::read_json(parsed$input, simplifyVector = FALSE)
if (!is.list(graph$nodes) || !is.list(graph$edges)) stop("Input must contain `nodes` and `edges` arrays.", call. = FALSE)
short_titles <- list()
if (!is.null(parsed$short_title_overrides)) {
  if (!file.exists(parsed$short_title_overrides)) {
    stop("Short-title sidecar not found: ", parsed$short_title_overrides, call. = FALSE)
  }
  sidecar <- jsonlite::read_json(parsed$short_title_overrides, simplifyVector = FALSE)
  short_titles <- sidecar$short_titles
  if (is.null(short_titles)) short_titles <- list()
  if (!is.list(short_titles) || is.null(names(short_titles))) {
    stop("Short-title sidecar must contain a named `short_titles` object.", call. = FALSE)
  }
  short_titles <- short_titles[nzchar(names(short_titles))]
  short_titles <- lapply(short_titles, function(value) trimws(as.character(value[[1L]])))
  short_titles <- short_titles[vapply(short_titles, function(value) length(value) && !is.na(value[[1L]]) && nzchar(value[[1L]]), logical(1L))]
}
graph_json <- jsonlite::toJSON(graph, auto_unbox = TRUE, null = "null", dataframe = "rows")
graph_json <- gsub("</", "<\\\\/", graph_json, fixed = TRUE)
short_titles_json <- jsonlite::toJSON(short_titles, auto_unbox = TRUE, null = "null")
short_titles_json <- gsub("</", "<\\\\/", short_titles_json, fixed = TRUE)

html <- paste0(
  "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>Literature Relationship Graph</title>",
  "<script src=\"https://unpkg.com/cytoscape@3.30.4/dist/cytoscape.min.js\"></script><style>",
  "*{box-sizing:border-box}body{margin:0;background:#f4f0e8;color:#17231f;font:14px Georgia,serif}header{padding:16px 22px;background:#173b35;color:#f7f0dc;display:flex;gap:16px;align-items:center}h1{font-size:20px;margin:0;letter-spacing:.02em}#search{margin-left:auto;width:260px;padding:7px 9px;border:0;border-radius:3px;font:13px Georgia,serif}.layout{border:1px solid #b2b8a6;background:#f7f0dc;padding:6px 9px;border-radius:3px;cursor:pointer;font:13px Georgia,serif}main{display:grid;grid-template-columns:minmax(0,1fr) 310px;height:calc(100vh - 58px)}#cy{min-height:500px;background:radial-gradient(circle at 20% 20%,#fffdf7,#e7eee5)}aside{border-left:1px solid #bdc7be;background:#fffdf7;padding:18px;overflow:auto}aside h2{font-size:16px;margin:0 0 10px;color:#173b35}.muted{color:#64736a;line-height:1.45}dl{margin:0}dt{font-weight:bold;color:#31584e;margin-top:12px}dd{margin:3px 0;white-space:pre-wrap;line-height:1.4}@media(max-width:780px){main{grid-template-columns:1fr;grid-template-rows:62vh auto}aside{border-left:0;border-top:1px solid #bdc7be}}
  </style></head><body><header><h1>Literature Relationship Graph</h1><button class=\"layout\" id=\"hierarchy\">Hierarchy</button><button class=\"layout\" id=\"network\">Network</button><input id=\"search\" placeholder=\"Filter ids or titles\"></header><main><div id=\"cy\"></div><aside><h2>Graph Details</h2><div id=\"detail\" class=\"muted\">Select a paper or relationship.</div></aside></main><script>",
  "const graph=", graph_json, ";function edgeClass(edge){const token=(String(edge.relationship||'')+' '+String(edge.anchor_role||'')).toLowerCase();if(token.includes('builds_on')||token.includes('foundation'))return'foundation';if(token.includes('extends'))return'extension';if(token.includes('compare')||token.includes('contrast'))return'comparison';return'context'}const nodes=graph.nodes.map(n=>({data:{id:n.id,label:n.title||n.ref_id,ref_id:n.ref_id,node_type:n.node_type,depth:n.depth,is_root:n.is_root,summary:n.summary,theoretical_mechanism:n.theoretical_mechanism,github_urls:n.github_urls},classes:n.is_root?'root':''}));const edges=graph.edges.map(e=>({data:{id:e.id,source:e.source,target:e.target,anchor_role:e.anchor_role,relationship:e.relationship,confidence:e.confidence,reason:e.reason},classes:edgeClass(e)}));",
  "const cy=cytoscape({container:document.getElementById('cy'),elements:{nodes,edges},style:[{selector:'node',style:{'label':'data(label)','font-size':10,'text-wrap':'wrap','text-max-width':125,'background-color':'#4c7a69','color':'#17231f','text-outline-color':'#fffdf7','text-outline-width':2,'width':28,'height':28}},{selector:'node:selected',style:{'border-width':3,'border-color':'#f0a500'}},{selector:'node[node_type = \"external\"]',style:{'background-color':'#9aa29b','shape':'diamond'}},{selector:'node.root',style:{'background-color':'#c77736','width':36,'height':36}},{selector:'edge',style:{'width':1.4,'target-arrow-shape':'triangle','curve-style':'bezier'}},{selector:'edge.foundation',style:{'line-color':'#31584e','target-arrow-color':'#31584e','line-style':'solid'}},{selector:'edge.extension',style:{'line-color':'#c77736','target-arrow-color':'#c77736','line-style':'dashed'}},{selector:'edge.comparison',style:{'line-color':'#a6863d','target-arrow-color':'#a6863d','line-style':'dotted'}},{selector:'edge.context',style:{'line-color':'#839388','target-arrow-color':'#839388','line-style':'solid'}}],layout:{name:'breadthfirst',directed:true,padding:40,spacingFactor:1.25}});",
  "const detail=document.getElementById('detail');function text(v){return v===null||v===undefined||v===''?'Not recorded':v}function esc(v){return String(text(v)).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]))}function show(rows){detail.innerHTML='<dl>'+rows.map(([k,v])=>'<dt>'+esc(k)+'</dt><dd>'+esc(v)+'</dd>').join('')+'</dl>'}cy.on('tap','node',e=>{const n=e.target.data();show([['Reference id',n.ref_id],['Title',n.label],['Summary',n.summary],['Theoretical mechanism',n.theoretical_mechanism],['GitHub URLs',n.github_urls],['Storage',n.node_type],['Depth',n.depth],['Root',n.is_root?'yes':'no']])});cy.on('tap','edge',e=>{const d=e.target.data();show([['Relationship',d.relationship],['Anchor role',d.anchor_role],['Confidence',d.confidence],['Reason',d.reason]])});document.getElementById('hierarchy').onclick=()=>cy.layout({name:'breadthfirst',directed:true,padding:40,spacingFactor:1.25}).run();document.getElementById('network').onclick=()=>cy.layout({name:'cose',padding:40,animate:false,idealEdgeLength:120}).run();document.getElementById('search').oninput=e=>{const q=e.target.value.trim().toLowerCase();cy.nodes().forEach(n=>{const visible=!q||String(n.data('ref_id')).toLowerCase().includes(q)||String(n.data('label')).toLowerCase().includes(q);n.style('display',visible?'element':'none')});cy.edges().forEach(edge=>edge.style('display',edge.source().style('display')==='none'||edge.target().style('display')==='none'?'none':'element'))};const roots=Array.isArray(graph.meta.root_ref_ids)?graph.meta.root_ref_ids:[graph.meta.root_ref_ids];show([['Roots',roots.filter(Boolean).join(', ')],['Nodes',graph.meta.returned_nodes],['Edges',graph.meta.returned_edges],['External anchors',graph.meta.external_nodes],['Truncated nodes',graph.meta.truncated_nodes]]);</script></body></html>"
)

legend_markup <- paste0(
  "<style>#edge-legend{width:29px;height:29px;padding:0;border:1px solid #b2b8a6;border-radius:50%;background:#f7f0dc;color:#173b35;cursor:pointer;font:700 16px Georgia,serif;line-height:1}#edge-legend-modal[hidden]{display:none}#edge-legend-modal{position:fixed;inset:0;z-index:10;display:grid;place-items:center;padding:20px;background:rgba(23,35,31,.48)}.legend-card{position:relative;width:min(460px,100%);padding:22px;background:#fffdf7;border:1px solid #bdc7be;box-shadow:0 18px 50px rgba(0,0,0,.28)}.legend-card h2{margin:0 36px 14px 0;color:#173b35}.legend-card p{line-height:1.45}.legend-close{position:absolute;top:10px;right:12px;border:0;background:transparent;color:#31584e;font:22px Georgia,serif;cursor:pointer}.legend-row{display:flex;align-items:center;gap:10px;margin:10px 0}.edge-sample{position:relative;width:56px;border-top:3px solid #31584e}.edge-sample:after{content:'';position:absolute;right:-1px;top:-6px;border-left:8px solid #31584e;border-top:5px solid transparent;border-bottom:5px solid transparent}.edge-sample.extension{border-top-color:#c77736;border-top-style:dashed}.edge-sample.extension:after{border-left-color:#c77736}.edge-sample.comparison{border-top-color:#a6863d;border-top-style:dotted}.edge-sample.comparison:after{border-left-color:#a6863d}.edge-sample.context{border-top-color:#839388}.edge-sample.context:after{border-left-color:#839388}</style>",
  "<script>const networkButton=document.getElementById('network');networkButton.insertAdjacentHTML('afterend','<button id=\"edge-legend\" type=\"button\" aria-label=\"Show edge legend\" title=\"Edge legend\">&#9432;</button>');document.body.insertAdjacentHTML('beforeend','<div id=\"edge-legend-modal\" hidden><section class=\"legend-card\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"edge-legend-title\"><button class=\"legend-close\" id=\"edge-legend-close\" type=\"button\" aria-label=\"Close edge legend\">&times;</button><h2 id=\"edge-legend-title\">Edge styles</h2><div class=\"legend-row\"><span class=\"edge-sample\"></span><span><strong>Foundation</strong>: builds on or cites a foundation.</span></div><div class=\"legend-row\"><span class=\"edge-sample extension\"></span><span><strong>Extension</strong>: extends prior work.</span></div><div class=\"legend-row\"><span class=\"edge-sample comparison\"></span><span><strong>Comparison</strong>: compares or contrasts methods.</span></div><div class=\"legend-row\"><span class=\"edge-sample context\"></span><span><strong>Context</strong>: other contextual relationship.</span></div><p>Arrows point from the citing paper to its anchored reference.</p></section></div>');const legendModal=document.getElementById('edge-legend-modal');const closeLegend=()=>{legendModal.hidden=true};document.getElementById('edge-legend').onclick=()=>{legendModal.hidden=false};document.getElementById('edge-legend-close').onclick=closeLegend;legendModal.onclick=e=>{if(e.target===legendModal)closeLegend()};document.addEventListener('keydown',e=>{if(e.key==='Escape')closeLegend()});const graphNodesById=new Map(graph.nodes.map(node=>[node.id,node]));const fullTitle=node=>{const source=graphNodesById.get(node.id);return source&&source.title?source.title:node.ref_id};const setCanvasLabels=network=>{cy.nodes().forEach(node=>{const data=node.data();node.data('label',network?data.ref_id:fullTitle(data))})};cy.on('tap','node',e=>{const node=e.target.data();show([['Reference id',node.ref_id],['Title',fullTitle(node)],['Summary',node.summary],['Theoretical mechanism',node.theoretical_mechanism],['GitHub URLs',node.github_urls],['Storage',node.node_type],['Depth',node.depth],['Root',node.is_root?'yes':'no']])});document.getElementById('hierarchy').onclick=()=>{setCanvasLabels(false);cy.layout({name:'breadthfirst',directed:true,padding:40,spacingFactor:1.25}).run()};networkButton.onclick=()=>{setCanvasLabels(true);cy.layout({name:'cose',padding:40,animate:false,idealEdgeLength:120}).run()};</script>"
)
network_layout_markup <- "<script>const networkLayoutButton=document.getElementById('network');const hierarchyLayoutButton=document.getElementById('hierarchy');const setNetworkCanvas=network=>{setCanvasLabels(network);cy.style().selector('node').style({'width':network?20:28,'height':network?20:28,'text-valign':network?'bottom':'center','text-margin-y':network?8:0}).selector('node.root').style({'width':network?26:36,'height':network?26:36}).update()};hierarchyLayoutButton.onclick=()=>{setNetworkCanvas(false);cy.layout({name:'breadthfirst',directed:true,padding:40,spacingFactor:1.25}).run()};networkLayoutButton.onclick=()=>{setNetworkCanvas(true);cy.layout({name:'cose',padding:70,animate:false,nodeDimensionsIncludeLabels:true,avoidOverlap:true,idealEdgeLength:()=>180,nodeRepulsion:()=>9000}).run()};</script>"
legend_markup <- paste0(legend_markup, network_layout_markup)
cache_panel_markup <- paste0(
  "<style>#cache-panel{position:fixed;z-index:5;top:82px;left:18px;width:370px;height:260px;min-width:240px;min-height:130px;max-width:calc(100vw - 340px);max-height:calc(100vh - 100px);resize:both;overflow:hidden;border:1px solid #8ca095;background:#fffdf7;box-shadow:0 10px 26px rgba(23,35,31,.2)}#cache-panel-handle{display:flex;align-items:center;gap:8px;min-height:34px;padding:8px 11px;background:#173b35;color:#f7f0dc;cursor:move;user-select:none;font-weight:bold;letter-spacing:.02em}#cache-panel-toggle{width:18px;height:18px;padding:0;border:1px solid #cfe0d2;border-radius:50%;background:transparent;color:#f7f0dc;cursor:pointer;font:700 15px/14px Georgia,serif}#cache-panel-count{margin-left:auto;color:#cfe0d2;font-weight:normal;font-size:12px}#cache-panel-body{height:calc(100% - 34px);overflow:auto}#cache-panel.is-collapsed{width:30px!important;height:30px!important;min-width:0;min-height:0;resize:none}#cache-panel.is-collapsed #cache-panel-handle{width:30px;min-height:30px;padding:0;justify-content:center;cursor:default}#cache-panel.is-collapsed #cache-panel-body,#cache-panel.is-collapsed .cache-panel-title,#cache-panel.is-collapsed #cache-panel-count{display:none}.cache-table{width:100%;border-collapse:collapse;font-size:12px;table-layout:fixed}.cache-table th{position:sticky;top:0;background:#e7eee5;color:#31584e;text-align:left;padding:7px 9px;border-bottom:1px solid #bdc7be}.cache-table td{padding:6px 9px;border-bottom:1px solid #e1e5dc;vertical-align:top;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.cache-table th:first-child,.cache-table td:first-child{width:104px;font-family:ui-monospace,SFMono-Regular,Menlo,monospace}.cache-row{cursor:pointer}.cache-row:hover,.cache-row:focus{background:#f0e7cf;outline:none}</style>",
  "<script>const cachedGraphNodes=graph.nodes.filter(node=>node.node_type==='cached').sort((left,right)=>String(left.ref_id).localeCompare(String(right.ref_id)));const cacheRows=cachedGraphNodes.map(node=>'<tr class=\"cache-row\" tabindex=\"0\" data-node-id=\"'+esc(node.id)+'\"><td>'+esc(node.ref_id)+'</td><td title=\"'+esc(node.title||node.ref_id)+'\">'+esc(node.title||node.ref_id)+'</td></tr>').join('');document.body.insertAdjacentHTML('beforeend','<section id=\"cache-panel\" aria-label=\"Cached graph nodes\"><div id=\"cache-panel-handle\"><button id=\"cache-panel-toggle\" type=\"button\" aria-expanded=\"true\" title=\"Collapse cached digests\">−</button><span class=\"cache-panel-title\">Cached digests</span><span id=\"cache-panel-count\">'+cachedGraphNodes.length+'</span></div><div id=\"cache-panel-body\"><table class=\"cache-table\"><thead><tr><th>ref_id</th><th>title</th></tr></thead><tbody>'+cacheRows+'</tbody></table></div></section>');const cachePanel=document.getElementById('cache-panel');const cacheHandle=document.getElementById('cache-panel-handle');const cacheToggle=document.getElementById('cache-panel-toggle');let cacheRestoreSize=null;let cacheDrag=null;cacheToggle.addEventListener('click',()=>{if(cachePanel.classList.contains('is-collapsed')){cachePanel.classList.remove('is-collapsed');cachePanel.style.width=cacheRestoreSize?cacheRestoreSize.width:'370px';cachePanel.style.height=cacheRestoreSize?cacheRestoreSize.height:'260px';cacheToggle.textContent='−';cacheToggle.title='Collapse cached digests';cacheToggle.setAttribute('aria-expanded','true');return}const box=cachePanel.getBoundingClientRect();cacheRestoreSize={width:box.width+'px',height:box.height+'px'};cachePanel.classList.add('is-collapsed');cachePanel.style.width='30px';cachePanel.style.height='30px';cacheToggle.textContent='+';cacheToggle.title='Expand cached digests';cacheToggle.setAttribute('aria-expanded','false')});cacheHandle.addEventListener('pointerdown',event=>{if(event.target.closest('#cache-panel-toggle'))return;const box=cachePanel.getBoundingClientRect();cacheDrag={offsetX:event.clientX-box.left,offsetY:event.clientY-box.top};cacheHandle.setPointerCapture(event.pointerId);event.preventDefault()});cacheHandle.addEventListener('pointermove',event=>{if(!cacheDrag)return;const maxLeft=Math.max(0,window.innerWidth-cachePanel.offsetWidth);const maxTop=Math.max(0,window.innerHeight-cachePanel.offsetHeight);cachePanel.style.left=Math.min(maxLeft,Math.max(0,event.clientX-cacheDrag.offsetX))+'px';cachePanel.style.top=Math.min(maxTop,Math.max(0,event.clientY-cacheDrag.offsetY))+'px';cachePanel.style.right='auto';cachePanel.style.bottom='auto'});const stopCacheDrag=()=>{cacheDrag=null};cacheHandle.addEventListener('pointerup',stopCacheDrag);cacheHandle.addEventListener('pointercancel',stopCacheDrag);const focusGraphNode=row=>{const node=cy.getElementById(row.dataset.nodeId);if(!node.length)return;const data=node.data();cy.elements().unselect();node.select();show([['Reference id',data.ref_id],['Title',fullTitle(data)],['Summary',data.summary],['Theoretical mechanism',data.theoretical_mechanism],['GitHub URLs',data.github_urls],['Storage',data.node_type],['Depth',data.depth],['Root',data.is_root?'yes':'no']]);cy.animate({center:{eles:node}},{duration:250})};document.querySelectorAll('.cache-row').forEach(row=>{row.addEventListener('click',()=>focusGraphNode(row));row.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();focusGraphNode(row)}})});</script>"
)
short_title_markup <- paste0(
  "<style>#short-title-export{border:1px solid #b2b8a6;background:#f7f0dc;padding:6px 9px;border-radius:3px;cursor:pointer;font:13px Georgia,serif}#short-title-input{width:100%;padding:5px 6px;border:1px solid #8ca095;border-radius:2px;background:#fffdf7;color:#17231f;font:inherit}</style>",
  "<script>const shortTitleOverrides=", short_titles_json, ";const shortTitleFor=data=>{const value=shortTitleOverrides[data.ref_id];return typeof value==='string'&&value.trim()?value.trim():data.ref_id};const setShortCanvas=network=>{cy.nodes().forEach(node=>{const data=node.data();const shortTitle=shortTitleFor(data);node.data('short_title',shortTitle);node.data('label',shortTitle)});cy.style().selector('node').style({'width':network?20:28,'height':network?20:28,'text-valign':network?'bottom':'center','text-margin-y':network?8:0}).selector('node.root').style({'width':network?26:36,'height':network?26:36}).update()};const showShortTitleNode=data=>{const shortTitle=shortTitleFor(data);detail.innerHTML='<dl><dt>Reference id</dt><dd>'+esc(data.ref_id)+'</dd><dt>Short title</dt><dd><input id=\"short-title-input\" type=\"text\" value=\"'+esc(shortTitle)+'\" aria-label=\"Short title\"></dd><dt>Title</dt><dd>'+esc(fullTitle(data))+'</dd><dt>Summary</dt><dd>'+esc(data.summary)+'</dd><dt>Theoretical mechanism</dt><dd>'+esc(data.theoretical_mechanism)+'</dd><dt>GitHub URLs</dt><dd>'+esc(data.github_urls)+'</dd><dt>Storage</dt><dd>'+esc(data.node_type)+'</dd><dt>Depth</dt><dd>'+esc(data.depth)+'</dd><dt>Root</dt><dd>'+esc(data.is_root?'yes':'no')+'</dd></dl>';const input=document.getElementById('short-title-input');const apply=()=>{const value=input.value.trim();if(!value||value===data.ref_id)delete shortTitleOverrides[data.ref_id];else shortTitleOverrides[data.ref_id]=value;const next=shortTitleFor(data);const node=cy.getElementById(data.id);node.data('short_title',next);node.data('label',next)};input.addEventListener('input',apply);input.addEventListener('blur',()=>{apply();input.value=shortTitleFor(data)})};cy.on('tap','node',event=>showShortTitleNode(event.target.data()));document.querySelectorAll('.cache-row').forEach(row=>row.addEventListener('click',()=>{const node=cy.getElementById(row.dataset.nodeId);if(node.length)showShortTitleNode(node.data())}));const networkLayout=()=>{setShortCanvas(true);cy.layout({name:'cose',padding:70,animate:false,nodeDimensionsIncludeLabels:true,avoidOverlap:true,idealEdgeLength:()=>180,nodeRepulsion:()=>9000}).run()};const hierarchyLayout=()=>{setShortCanvas(false);cy.layout({name:'breadthfirst',directed:true,padding:40,spacingFactor:1.25}).run()};document.getElementById('hierarchy').onclick=hierarchyLayout;networkButton.onclick=networkLayout;networkButton.insertAdjacentHTML('afterend','<button id=\"short-title-export\" type=\"button\" title=\"Download short-title overrides\">Export labels</button>');document.getElementById('short-title-export').onclick=()=>{const titles={};Object.keys(shortTitleOverrides).sort().forEach(refId=>{const value=String(shortTitleOverrides[refId]||'').trim();if(value&&value!==refId)titles[refId]=value});const blob=new Blob([JSON.stringify({schema_version:1,short_titles:titles},null,2)+'\\n'],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='literature_graph_short_titles.json';link.click();URL.revokeObjectURL(url)};hierarchyLayout();</script>"
)
cache_filter_markup <- "<style>#cache-panel .cache-table th{cursor:text}#cache-panel .cache-table th input{width:100%;border:0;border-radius:0;background:#fffdf7;color:#17231f;font:inherit;outline:1px solid #31584e;padding:2px 3px}</style><script>const cacheFilterValues={ref_id:'',title:''};const cacheFilterRows=Array.from(document.querySelectorAll('#cache-panel .cache-row'));const applyCacheFilters=()=>{cacheFilterRows.forEach(row=>{const refId=row.cells[0].textContent.toLowerCase();const title=row.cells[1].textContent.toLowerCase();row.hidden=Boolean((cacheFilterValues.ref_id&&!refId.includes(cacheFilterValues.ref_id))||(cacheFilterValues.title&&!title.includes(cacheFilterValues.title)))})};document.querySelectorAll('#cache-panel .cache-table th').forEach(header=>{const column=header.cellIndex===0?'ref_id':'title';header.addEventListener('click',()=>{if(header.querySelector('input'))return;const input=document.createElement('input');input.type='text';input.value=cacheFilterValues[column];input.setAttribute('aria-label','Filter '+column);header.replaceChildren(input);input.addEventListener('input',()=>{cacheFilterValues[column]=input.value.toLowerCase();applyCacheFilters()});input.focus()})});</script>"
detail_splitter_markup <- "<style>main{grid-template-columns:minmax(0,1fr) 6px 310px}aside{border-left:0}#detail-splitter{grid-column:2;grid-row:1;cursor:col-resize;background:#bdc7be;transition:background .15s}#detail-splitter:hover,#detail-splitter:active{background:#31584e}@media(max-width:780px){main{grid-template-columns:1fr}#detail-splitter{display:none}}</style><script>const graphMain=document.querySelector('main');const detailAside=document.querySelector('aside');detailAside.insertAdjacentHTML('beforebegin','<div id=\"detail-splitter\" role=\"separator\" aria-orientation=\"vertical\" aria-label=\"Resize graph details panel\"></div>');const detailSplitter=document.getElementById('detail-splitter');const resizeDetailPanel=clientX=>{if(window.matchMedia('(max-width:780px)').matches)return;const box=graphMain.getBoundingClientRect();const minCanvas=260;const minDetail=220;const maxDetail=Math.max(minDetail,box.width-minCanvas-6);const detailWidth=Math.min(maxDetail,Math.max(minDetail,Math.round(box.right-clientX)));graphMain.style.gridTemplateColumns='minmax('+minCanvas+'px,1fr) 6px '+detailWidth+'px'};detailSplitter.addEventListener('pointerdown',event=>{detailSplitter.setPointerCapture(event.pointerId);document.body.style.cursor='col-resize';resizeDetailPanel(event.clientX);event.preventDefault()});detailSplitter.addEventListener('pointermove',event=>{if(detailSplitter.hasPointerCapture(event.pointerId))resizeDetailPanel(event.clientX)});const stopDetailResize=event=>{if(detailSplitter.hasPointerCapture(event.pointerId))detailSplitter.releasePointerCapture(event.pointerId);document.body.style.cursor=''};detailSplitter.addEventListener('pointerup',stopDetailResize);detailSplitter.addEventListener('pointercancel',stopDetailResize);</script>"
html <- sub("</body>", paste0(legend_markup, cache_panel_markup, short_title_markup, cache_filter_markup, detail_splitter_markup, "</body>"), html, fixed = TRUE)

dir.create(dirname(parsed$output), recursive = TRUE, showWarnings = FALSE)
writeLines(html, parsed$output, useBytes = TRUE)
writeLines(jsonlite::toJSON(list(status = "ok", output = normalizePath(parsed$output, winslash = "/", mustWork = FALSE)), auto_unbox = TRUE), con = stdout())
